require "rails_helper"

RSpec.describe "Timekeeping::Handoff::TimekeepingStore failures" do
  # Acceptance: "Timekeeping::Handoff::TimekeepingStore implements the same
  # interface as Timekeeping::Handoff::MonolithStore". Callers see one error
  # type for both stores, so a refusal or timeout can never read as success
  # or leak a Net:: error.
  it "raises the store error for a refused or timed-out call and never sends a request with a blank token" do
    base_url = "http://timekeeping-handoff.test"
    sequence_url = "#{base_url}/internal/v1/handoff/entry_id_sequence"
    store = Timekeeping::Handoff::TimekeepingStore.new(base_url:, token: "service-token")

    stub_request(:post, sequence_url).to_return(
      status: 409, body: JSON.generate(reason: "handoff_refused"), headers: { "Content-Type" => "application/json" }
    )
    expect { store.advance_entry_id_sequence(above: 5) }.to raise_error(Timekeeping::Handoff::Store::Error)

    stub_request(:post, sequence_url).to_timeout
    expect { store.advance_entry_id_sequence(above: 5) }.to raise_error(Timekeeping::Handoff::Store::Error)

    WebMock.reset!
    blank_token_store = Timekeeping::Handoff::TimekeepingStore.new(base_url:, token: "")
    expect { blank_token_store.highest_outbox_position }.to raise_error(Timekeeping::Handoff::Store::Error)
    expect(a_request(:any, /timekeeping-handoff\.test/)).not_to have_been_made
  end
end
